$pdo=db();if(!$pdo){fwrite(STDERR,"SKIP: database unavailable\n");exit(0);} $snapshot=(new WorldService($pdo))->solarSystemSnapshot(1);if(!in_array($snapshot['state'],['ready','empty','protected'],true))throw new RuntimeException('Unexpected Solar Systems state.');foreach(['system','systems','planets','fleet_lanes','gate','telemetry','cooldown','formula','states'] as $key)if(!array_key_exists($key,$snapshot))throw new RuntimeException('Missing Solar Systems contract key: '.$key);if($snapshot['state']==='ready'){if(!$snapshot['system']['coordinate'])throw new RuntimeException('Missing validated system coordinate.');foreach(['sensor_range','mothership_science','discovery','scan_power'] as $key)if(!array_key_exists($key,$snapshot['telemetry']))throw new RuntimeException('Missing scan telemetry: '.$key);$lastOrbit=0;foreach($snapshot['planets'] as $planet){if((int)$planet['orbit_position']<$lastOrbit)throw new RuntimeException('Orbit map is not ordered.');$lastOrbit=(int)$planet['orbit_position'];if(!array_key_exists('moons',$planet))throw new RuntimeException('Planet is missing moon registry.');}if(!array_key_exists('available',$snapshot['gate'])||!array_key_exists('status',$snapshot['gate']))throw new RuntimeException('Missing gate status.');}echo 'PASS: Solar Systems coordinate access, discovery, orbit map, moons, gate status, telemetry, fleet lanes, and anomaly contract verified'.PHP_EOL;
